def floyd_warshall(dist):            # dist: n x n, inf where no edge
    n = len(dist)
    for k in range(n):
        for i in range(n):
            for j in range(n):
                if dist[i][k] + dist[k][j] < dist[i][j]:
                    dist[i][j] = dist[i][k] + dist[k][j]
    return dist

class Solution {
public:
    int findTheCity(int n, vector<vector<int>>& edges, int threshold) {
        const int INF = 1e9;
        vector<vector<int>> d(n, vector<int>(n, INF));
        for (int i = 0; i < n; i++) d[i][i] = 0;
        for (auto& e : edges) { d[e[0]][e[1]] = e[2]; d[e[1]][e[0]] = e[2]; }
        for (int k = 0; k < n; k++)
            for (int i = 0; i < n; i++)
                for (int j = 0; j < n; j++)
                    if (d[i][k] + d[k][j] < d[i][j]) d[i][j] = d[i][k] + d[k][j];
        int best = -1, bestCnt = INT_MAX;
        for (int i = 0; i < n; i++) {
            int cnt = 0;
            for (int j = 0; j < n; j++) if (i != j && d[i][j] <= threshold) cnt++;
            if (cnt <= bestCnt) { bestCnt = cnt; best = i; }
        }
        return best;
    }
};

class Solution:
    def findTheCity(self, n, edges, threshold):
        INF = float('inf')
        d = [[INF] * n for _ in range(n)]
        for i in range(n):
            d[i][i] = 0
        for u, v, w in edges:
            d[u][v] = d[v][u] = w
        for k in range(n):
            for i in range(n):
                for j in range(n):
                    if d[i][k] + d[k][j] < d[i][j]:
                        d[i][j] = d[i][k] + d[k][j]
        best, best_cnt = -1, INF
        for i in range(n):
            cnt = sum(1 for j in range(n) if i != j and d[i][j] <= threshold)
            if cnt <= best_cnt:
                best_cnt, best = cnt, i
        return best

class Solution {
public:
    vector<bool> checkIfPrerequisite(int n, vector<vector<int>>& pre, vector<vector<int>>& queries) {
        vector<vector<bool>> reach(n, vector<bool>(n, false));
        for (auto& p : pre) reach[p[0]][p[1]] = true;
        for (int k = 0; k < n; k++)
            for (int i = 0; i < n; i++)
                if (reach[i][k])
                    for (int j = 0; j < n; j++)
                        if (reach[k][j]) reach[i][j] = true;
        vector<bool> res;
        for (auto& q : queries) res.push_back(reach[q[0]][q[1]]);
        return res;
    }
};

class Solution:
    def checkIfPrerequisite(self, n, prerequisites, queries):
        reach = [[False] * n for _ in range(n)]
        for a, b in prerequisites:
            reach[a][b] = True
        for k in range(n):
            for i in range(n):
                if reach[i][k]:
                    for j in range(n):
                        if reach[k][j]:
                            reach[i][j] = True
        return [reach[a][b] for a, b in queries]

class Solution {
public:
    vector<double> calcEquation(vector<vector<string>>& eq, vector<double>& vals, vector<vector<string>>& queries) {
        unordered_map<string,int> id; int n = 0;
        for (auto& e : eq) for (auto& s : e) if (!id.count(s)) id[s] = n++;
        vector<vector<double>> d(n, vector<double>(n, 0.0));
        for (int i = 0; i < n; i++) d[i][i] = 1.0;
        for (int i = 0; i < (int)eq.size(); i++) {
            int a = id[eq[i][0]], b = id[eq[i][1]];
            d[a][b] = vals[i]; d[b][a] = 1.0 / vals[i];
        }
        for (int k = 0; k < n; k++)
            for (int i = 0; i < n; i++)
                for (int j = 0; j < n; j++)
                    if (d[i][k] && d[k][j]) d[i][j] = d[i][k] * d[k][j];
        vector<double> res;
        for (auto& q : queries) {
            if (!id.count(q[0]) || !id.count(q[1]) || d[id[q[0]]][id[q[1]]] == 0.0) res.push_back(-1.0);
            else res.push_back(d[id[q[0]]][id[q[1]]]);
        }
        return res;
    }
};

class Solution:
    def calcEquation(self, equations, values, queries):
        idx = {}
        for a, b in equations:
            idx.setdefault(a, len(idx)); idx.setdefault(b, len(idx))
        n = len(idx)
        d = [[0.0] * n for _ in range(n)]
        for i in range(n):
            d[i][i] = 1.0
        for (a, b), v in zip(equations, values):
            d[idx[a]][idx[b]] = v
            d[idx[b]][idx[a]] = 1.0 / v
        for k in range(n):
            for i in range(n):
                if d[i][k]:
                    for j in range(n):
                        if d[k][j]:
                            d[i][j] = d[i][k] * d[k][j]
        res = []
        for a, b in queries:
            if a in idx and b in idx and d[idx[a]][idx[b]]:
                res.append(d[idx[a]][idx[b]])
            else:
                res.append(-1.0)
        return res

class Solution {
public:
    long long minimumCost(string source, string target, vector<char>& original, vector<char>& changed, vector<int>& cost) {
        const long long INF = 1e18;
        vector<vector<long long>> d(26, vector<long long>(26, INF));
        for (int i = 0; i < 26; i++) d[i][i] = 0;
        for (int i = 0; i < (int)cost.size(); i++) {
            int u = original[i] - 'a', v = changed[i] - 'a';
            d[u][v] = min(d[u][v], (long long)cost[i]);
        }
        for (int k = 0; k < 26; k++)
            for (int i = 0; i < 26; i++)
                for (int j = 0; j < 26; j++)
                    if (d[i][k] + d[k][j] < d[i][j]) d[i][j] = d[i][k] + d[k][j];
        long long total = 0;
        for (int i = 0; i < (int)source.size(); i++) {
            long long c = d[source[i] - 'a'][target[i] - 'a'];
            if (c == INF) return -1;
            total += c;
        }
        return total;
    }
};

class Solution:
    def minimumCost(self, source, target, original, changed, cost):
        INF = float('inf')
        d = [[INF] * 26 for _ in range(26)]
        for i in range(26):
            d[i][i] = 0
        for o, c, w in zip(original, changed, cost):
            u, v = ord(o) - 97, ord(c) - 97
            d[u][v] = min(d[u][v], w)
        for k in range(26):
            for i in range(26):
                if d[i][k] < INF:
                    for j in range(26):
                        if d[i][k] + d[k][j] < d[i][j]:
                            d[i][j] = d[i][k] + d[k][j]
        total = 0
        for s, t in zip(source, target):
            c = d[ord(s) - 97][ord(t) - 97]
            if c == INF:
                return -1
            total += c
        return total

class Solution {
public:
    vector<vector<int>> allPairs(int n, vector<vector<int>>& edges) {
        const int INF = 1e9;
        vector<vector<int>> d(n, vector<int>(n, INF));
        for (int i = 0; i < n; i++) d[i][i] = 0;
        for (auto& e : edges) d[e[0]][e[1]] = min(d[e[0]][e[1]], e[2]);
        for (int k = 0; k < n; k++)
            for (int i = 0; i < n; i++)
                for (int j = 0; j < n; j++)
                    if (d[i][k] + d[k][j] < d[i][j]) d[i][j] = d[i][k] + d[k][j];
        return d;
    }
};

class Solution:
    def allPairs(self, n, edges):
        INF = float('inf')
        d = [[INF] * n for _ in range(n)]
        for i in range(n):
            d[i][i] = 0
        for u, v, w in edges:
            d[u][v] = min(d[u][v], w)
        for k in range(n):
            for i in range(n):
                dik = d[i][k]
                if dik < INF:
                    row = d[i]
                    for j in range(n):
                        if dik + d[k][j] < row[j]:
                            row[j] = dik + d[k][j]
        return d
